    /\ wr_at asegs mc (shad RLO1) (shad RHI1 - shad RLO1) /\ wr_at asegs mc (shad RLO2) (shad RHI2 - shad RLO2).

  (* [comment removed for export] *)
  Definition BND : Prop :=
    (0 <= lo /\ lo <= bv_unsigned sp - 2224 /\ KHIGH <= lo /\ 0 <= n < 2^64 /\ n <= 2^40
